import rawDetails from '../../data/details.json';
import rawProfiles from '../../data/profiles.json';
import type { PartKind, PartModel, Profile, Saber, Style, SurfaceDetails } from '../types';

/** Outlines generated by data/build_profiles.py, keyed by `kind.model` (plus `pommel.adaptor.extra`). */
const PROFILES = rawProfiles as unknown as Record<string, Profile>;
/** Grooves, holes and knurling read from the size chart by data/build_details.py. */
const DETAILS = rawDetails as unknown as Record<string, SurfaceDetails>;

/** A part whose outline comes from profiles.json; its length is where the outline ends. */
function traced(key: string, name: string, extra: Partial<PartModel> = {}): PartModel {
  const profile = PROFILES[key];
  if (!profile) throw new Error(`Missing profile ${key} in data/profiles.json`);
  return { name, profile, len: profile[profile.length - 1][0], details: DETAILS[key], ...extra };
}

const noDetails = (): SurfaceDetails => ({ grooves: [], holes: [], knurls: [], ribs: [] });

/**
 * EVO parts are not on the size chart, so their details are read by eye from the lamadiluce.it product
 * photos (Dark Matter), in mm along the part. Lines at the outline's corners are drawn automatically.
 */
const EVO_BODY_DETAILS: SurfaceDetails = {
  ...noDetails(),
  holes: [
    // USB-C charging slot, a pill cut across the groove next to the pommel collar.
    [22.2, -5.5, 8.5, 2.2],
    // Speaker holes: two drilled bands by the emitter collar, two holes of each in view (about 90° apart
    // around the band, so the far one is seen almost edge-on).
    [141.3, -8, 2.6, 2.7], [141.3, 16.2, 1.2, 2.7],
    [128.5, -8, 2.6, 2.7], [128.5, 16.2, 1.2, 2.7],
  ],
};
/** The Mini body keeps the EVO ends and loses 30 mm of waist (see data/build_profiles.py). */
const EVO_MINI_BODY_DETAILS: SurfaceDetails = {
  ...EVO_BODY_DETAILS,
  holes: EVO_BODY_DETAILS.holes.map(([x, ...rest]) => [x > 111 ? x - 30 : x, ...rest]),
};

/** EVO2 emitter (aluminum photos): fins in the waist, set screws in the collar, and a column of
 * holes between the fins, running slightly diagonally, that glows with the blade (store's lit photos). */
const EVO2_LIGHT_HOLES = {
  /** x of each hole (mm from the collar end), from just above the collar to just under the rim. */
  x: [12.8, 16.3, 19.8, 23.3, 26.8, 30.3, 33.8, 37.3, 40.8],
  /** y of the first and last hole: the column leans slightly across the part. */
  yFrom: -1.5,
  yTo: 1.5,
  diameter: 1.5,
};
const EVO2_EMITTER_DETAILS: SurfaceDetails = {
  ...noDetails(),
  grooves: [4.8, 10.6, 15, 19.3, 22.2, 25.9, 28.9, 32.6].map((x) => [x, 1, -21, 21] as [number, number, number, number]),
  holes: [[2.4, 0, 1.7, 1.7], [2.4, -14.5, 1.1, 1.5], [2.4, 14.5, 1.1, 1.5]],
  lightHoles: EVO2_LIGHT_HOLES.x.map((x, i, all) => {
    const { yFrom, yTo, diameter } = EVO2_LIGHT_HOLES;
    return [x, yFrom + ((yTo - yFrom) * i) / (all.length - 1), diameter] as [number, number, number];
  }),
};

/** NXT emitter (Stellar Eclipse and aluminum photos): S-curved slots milled along the waist, each with
 * three through-holes inside it that let the blade's light out, and set screws in the collar.
 * Positions read by eye, so approximate. */
const NXT_SLOTS: [number, number][][] = [
  [[13, -14], [18, -13], [24, -10], [30, -7.5], [36, -6.5], [40.5, -6.5]],
  [[13, 7], [18, 8.5], [24, 11], [30, 12.8], [36, 13.5], [40.5, 13.6]],
];
const NXT_EMITTER_DETAILS: SurfaceDetails = {
  ...noDetails(),
  holes: [[3.6, 0, 1.6, 1.6], [3.6, -14, 1.1, 1.4], [3.6, 14, 1.1, 1.4]],
  slots: NXT_SLOTS.map((points) => ({ points, width: 2.8 })),
  lightHoles: NXT_SLOTS.flatMap((slot) => [19.5, 26, 32.5].map((x) => [x, pointOn(slot, x), 2.1] as [number, number, number])),
};

/** y of a polyline at x (linear between its points). */
function pointOn(points: [number, number][], x: number): number {
  for (let i = 1; i < points.length; i++) {
    const [x1, y1] = points[i - 1];
    const [x2, y2] = points[i];
    if (x <= x2) return y1 + ((y2 - y1) * (x - x1)) / (x2 - x1);
  }
  return points[points.length - 1][1];
}

function ring(name: string, len: number, extra: Partial<PartModel> = {}): PartModel {
  return { name, len, profile: [[0, 18.4], [0.5, 19], [len - 0.5, 19], [len, 18.4]], ...extra };
}

/**
 * EVO coupler (aluminum photo p. 1504; the Maori edition, p. 5275, is the same tube engraved): a straight
 * tube the full 70 mm between the two bodies, with small chamfers at the ends. Four rows of 13 holes run
 * along it, 90° apart; the store photo looks between two rows, and so does the app (rows at ±45°, seen at
 * an angle). Holes about 3 mm across, 4.4 mm apart, centred on the tube. Proportions checked against the
 * photo after undoing its tilt (read from the end-face ellipse): the tube comes out 69 mm against 70.
 */
const EVO_COUPLER: Profile = [[0, 18.4], [0.8, 18.9], [69.2, 18.9], [70, 18.4]];
const EVO_COUPLER_HOLE_ROW_Y = 18.9 * Math.sin(Math.PI / 4);
const EVO_COUPLER_DETAILS: SurfaceDetails = {
  ...noDetails(),
  holes: Array.from({ length: 13 }, (_, i) => 35 + (i - 6) * 4.4).flatMap((x) =>
    [-1, 1].map((side) => [x, side * EVO_COUPLER_HOLE_ROW_Y, 3 * Math.cos(Math.PI / 4), 3] as [number, number, number, number]),
  ),
};

/*
 * Weights (g, empty) are the ones in the lamadiluce.it product descriptions, 12 Nov 2026. Parts of the same
 * kind and shape are taken to weigh the same: the logo ring as the 10 mm plain and Tribe rings (3.9 to 4.2 g),
 * the thin ring as a third of that. The store gives none for the couplers, the Pommel Adaptor and legacy parts.
 */
export const MODELS: Record<PartKind, Record<string, PartModel>> = {
  emitter: {
    evo: traced('emitter.evo', 'EVO Emitter', { weight: 66 }),
    nxt: traced('emitter.nxt', 'NXT Emitter', { approx: true, details: NXT_EMITTER_DETAILS, weight: 75 }),
    evo2: traced('emitter.evo2', 'EVO2 Emitter', { approx: true, details: EVO2_EMITTER_DETAILS, weight: 58 }),
    x2: traced('emitter.x2', 'X2 Emitter', { legacy: true }),
    sse1: traced('emitter.sse1', 'SSe-1 Emitter', { legacy: true }),
    sse2: traced('emitter.sse2', 'SSe-2 Emitter', { legacy: true }),
    sse3: traced('emitter.sse3', 'SSe-3 Emitter', { legacy: true }),
    artiglio: traced('emitter.artiglio', 'Artiglio Emitter', { legacy: true }),
  },
  body: {
    evo: traced('body.evo', 'EVO Main Body', { details: EVO_BODY_DETAILS, weight: 120 }),
    // The store gives 100 g for the aluminum Mini body and 102 g for the colored ones.
    mini: traced('body.mini', 'EVO Mini Main Body', { approx: true, details: EVO_MINI_BODY_DETAILS, weight: 101 }),
    sse1: traced('body.sse1', 'SSe-1 Main Body', { legacy: true }),
    sse3: traced('body.sse3', 'SSe-3 Main Body', { legacy: true }),
    sse2: traced('body.sse2', 'SSe-2 Main Body', { legacy: true }),
  },
  pommel: {
    evo: traced('pommel.evo', 'EVO Pommel', { weight: 66 }),
    mini: traced('pommel.mini', 'EVO Mini Pommel', { approx: true, weight: 38 }),
    adaptor: traced('pommel.adaptor', 'Pommel Adaptor', { profileExtra: PROFILES['pommel.adaptor.extra'] }),
    sse1: traced('pommel.sse1', 'SSe-1 Pommel', { legacy: true }),
    sse3std: traced('pommel.sse3std', 'SSe-3 Pommel (standard mask)', { legacy: true }),
    sse3extra: traced('pommel.sse3extra', 'SSe-3 Pommel (extra mask)', { legacy: true }),
    sse2: traced('pommel.sse2', 'SSe-2 Pommel', { legacy: true }),
  },
  coupler: {
    classic: { name: 'Polaris Coupler (2019)', len: 7, profile: [[0, 17.5], [7, 17.5]] },
    heavy: { name: 'Polaris Heavy Coupler', len: 20, approx: true, profile: [[0, 18.5], [20, 18.5]], grooves: [6, 14] },
    evo: { name: 'EVO Coupler', len: 70, profile: EVO_COUPLER, details: EVO_COUPLER_DETAILS },
    maori: { name: 'EVO Coupler Maori (limited)', len: 70, profile: EVO_COUPLER, details: EVO_COUPLER_DETAILS, mark: 'tribe' },
  },
  ring: {
    plain: ring('Plain Ring 10 mm', 10, { weight: 4 }),
    thin: ring('Thin Ring 3.3 mm', 3.3, { weight: 1.3 }),
    logo: ring('LamaDiLuce Ring', 10, { mark: 'star', weight: 4 }),
    tribe: ring('Ring Tribe', 10, { mark: 'tribe', weight: 4 }),
  },
};

