export const BLADE_RADIUS = 12.7;

export const BLADE_COLORS = ['#4aa3ff', '#3ddc6a', '#ff3b30', '#a259ff', '#f4f4f4', '#ffb22e'];

const DEFAULTS = { coupler: { model: 'evo', finish: 'aluminum' }, mask: 'standard', style: 'sword' } as const;

function preset(p: Omit<Saber, 'coupler' | 'mask' | 'style'> & Partial<Saber>): Saber {
  return { ...DEFAULTS, ...p, coupler: p.coupler ?? { ...DEFAULTS.coupler } };
}

