/** Fills fields added after v1 and rejects anything that does not describe a saber. */
export function normalizeSaber(input: unknown): Saber | null {
  const s = input as Partial<Saber> | null;
  if (!s || typeof s !== 'object') return null;
  const known = (kind: PartKind, p?: { model?: string }) => !!p && typeof p.model === 'string' && !!MODELS[kind][p.model];
  if (!known('emitter', s.emitter) || !known('body', s.body) || !known('pommel', s.pommel)) return null;
  if (!Array.isArray(s.ringsTop) || !Array.isArray(s.ringsBottom) || !s.blade) return null;
  return {
    ...DEFAULTS,
    ...(s as Saber),
    name: typeof s.name === 'string' ? s.name : 'Untitled',
    coupler: known('coupler', s.coupler) ? s.coupler! : { ...DEFAULTS.coupler },
    ringsTop: s.ringsTop.filter((r) => known('ring', r)),
    ringsBottom: s.ringsBottom.filter((r) => known('ring', r)),
  };
}
